export interface User {
  username: string;
  password: string;
  role: Role;
}

export interface AuthOptions {
  users: User[];
  secret: string;
  now?: () => Date;
}

export function createAuthHandler(
  options: AuthOptions,
): (req: Request) => Promise<Response> {
  const { users, secret } = options;
  const nowFn = options.now ?? (() => new Date());
  const revoked = new Set<string>();

  function json(status: number, body: unknown): Response {
    return new Response(JSON.stringify(body), {
      status,
      headers: { "Content-Type": "application/json; charset=utf-8" },
    });
  }

  function extractBearer(header: string | null): string | null {
    if (header === null) return null;
    const prefix = "Bearer ";
    if (!header.startsWith(prefix)) return null;
    const token = header.slice(prefix.length);
    if (token.length === 0) return null;
    return token;
  }

  function toB64Url(bytes: Uint8Array): string {
    let s = "";
    for (let i = 0; i < bytes.length; i++) {
      s += String.fromCharCode(bytes[i]);
    }
    return btoa(s).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
  }

  function fromB64Url(s: string): Uint8Array {
    const padded = s + "=".repeat((4 - (s.length % 4)) % 4);
    const bin = atob(padded.replace(/-/g, "+").replace(/_/g, "/"));
    const out = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) {
      out[i] = bin.charCodeAt(i);
    }
    return out;
  }

  async function makeToken(username: string): Promise<{ token: string; expiresAt: string }> {
    const t = nowFn();
    const exp = t.getTime() + 3_600_000;
    const nonce = crypto.getRandomValues(new Uint8Array(32));
    const nonceHex = Array.from(nonce).map((b) => b.toString(16).padStart(2, "0")).join("");
    const payload = JSON.stringify({ u: username, e: exp, n: nonceHex });
    const payloadB64 = toB64Url(new TextEncoder().encode(payload));
    const key = await crypto.subtle.importKey(
      "raw", new TextEncoder().encode(secret),
      { name: "HMAC", hash: "SHA-256" }, false, ["sign"],
    );
    const sig = await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(payload));
    const sigB64 = toB64Url(new Uint8Array(sig));
    return { token: `${payloadB64}.${sigB64}`, expiresAt: new Date(exp).toISOString() };
  }

  async function checkToken(raw: string): Promise<{ username: string; role: Role } | null> {
    if (revoked.has(raw)) return null;
    const dot = raw.indexOf(".");
    if (dot <= 0 || dot >= raw.length - 1) return null;
    const pB64 = raw.slice(0, dot);
    const sB64 = raw.slice(dot + 1);
    let payloadStr: string;
    try {
      payloadStr = new TextDecoder().decode(fromB64Url(pB64));
    } catch {
      return null;
    }
    let p: { u: string; e: number };
    try {
      const o = JSON.parse(payloadStr);
      if (typeof o !== "object" || o === null || Array.isArray(o)) return null;
      if (typeof o.u !== "string" || typeof o.e !== "number") return null;
      p = { u: o.u, e: o.e };
    } catch {
      return null;
    }
    let sigBytes: Uint8Array;
    try {
      sigBytes = fromB64Url(sB64);
    } catch {
      return null;
    }
    try {
      const key = await crypto.subtle.importKey(
        "raw", new TextEncoder().encode(secret),
        { name: "HMAC", hash: "SHA-256" }, false, ["verify"],
      );
      const ok = await crypto.subtle.verify("HMAC", key, sigBytes, new TextEncoder().encode(payloadStr));
      if (!ok) return null;
    } catch {
      return null;
    }
    if (nowFn().getTime() >= p.e) return null;
    const user = users.find((u) => u.username === p.u);
    if (!user) return null;
    return { username: user.username, role: user.role };
  }

  return async (req: Request): Promise<Response> => {
    const url = new URL(req.url);
    const path = url.pathname;
    const method = req.method;

    if (path === "/login" && method === "POST") {
      let body: string;
      try {
        body = await req.text();
      } catch {
        return json(400, { error: "invalid_request" });
      }
      let parsed: unknown;
      try {
        parsed = JSON.parse(body);
      } catch {
        return json(400, { error: "invalid_request" });
      }
      if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
        return json(400, { error: "invalid_request" });
      }
      const obj = parsed as Record<string, unknown>;
      if (typeof obj.username !== "string" || typeof obj.password !== "string") {
        return json(400, { error: "invalid_request" });
      }
      const user = users.find((u) => u.username === obj.username && u.password === obj.password);
      if (!user) return json(401, { error: "invalid_credentials" });
      const { token, expiresAt } = await makeToken(user.username);
      return json(200, { token, expiresAt });
    }

    // Authenticated routes
    if (
      (path === "/me" && method === "GET") ||
      (path === "/admin/stats" && method === "GET") ||
      (path === "/logout" && method === "POST")
    ) {
      const raw = extractBearer(req.headers.get("Authorization"));
      if (raw === null) return json(401, { error: "unauthorized" });
      const auth = await checkToken(raw);
      if (auth === null) return json(401, { error: "unauthorized" });

      if (path === "/me") {
        return json(200, { username: auth.username, role: auth.role });
      }

